@startuml

class OilCompany {}

class GasStation {
  + address : string
}

class Pump {
  + currentLevel : float
  + reorderingLevel : float
  + criticalLevel : float
  + isBlocked : boolean
}

class GasolineType {
  + name : string
}

class Reservoir {
  + quantity : float
}

class Customer {
  + name : string
  + isSuspended : boolean
  + isCardBlocked : boolean
  + slackThreshold : int
}

class RefuelCard {
  + cardNumber : string
}

class RefuelTurn {
  + startTime : time
  + endTime : time
  + quantity : float
}

class Invoice {
  + month : int
  + year : int
  + discount : float
}

class Payment {
  + date : date
  + amount : float
}

class DailyReport {
  + date : date
}

GasStation "1" -- "*" Pump : operates
Pump "*" -- "1" GasolineType : contains
Pump "1" *-- "1" Reservoir : has
GasStation "1" -- "*" DailyReport : produces
DailyReport "*" -- "*" Pump : reports on

Customer "1" -- "0..1" RefuelCard : owns
Customer "1" -- "*" RefuelTurn : performs
Customer "1" -- "*" Invoice : receives
Customer "1" -- "*" Payment : makes

Invoice "1" -- "*" RefuelTurn : includes
Invoice "1" -- "0..*" Payment : settled by

Pump "1" -- "0..1" RefuelTurn : used by

@enduml

